      "category": "concept"
    },
    {
      "name": "LR电路",
      "aliases": ["LR circuit", "LR电路"],
      "definition_snippet": "含电感 L 与电阻 R 的电路，方程 L(dI/dt)+RI=E(t)。",
      "category": "concept"
    },
    {
      "name": "RC电路",
      "aliases": ["RC circuit", "RC电路"],
      "definition_snippet": "含电阻 R 与电容 C 的电路，方程 R(dQ/dt)+Q/C=E(t)。",
      "category": "concept"
    },
    {
      "name": "LRC电路",
      "aliases": ["LRC circuit", "LRC电路"],
      "definition_snippet": "含电感、电阻、电容的电路，方程 LQ''+RQ'+Q/C=E(t)。",
      "category": "concept"
    },
    {
      "name": "放射性衰变",
      "aliases": ["radioactive decay", "放射性衰变"],
